const upstreamCatalog = [
  { id: 1, name: 'Laptop', price: 999, inventory: 42, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 128, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 64, available: true },
  { id: 4, name: 'Headphones', price: 199, inventory: 0, available: false },
  { id: 5, name: 'Watch', price: 299, inventory: 31, available: true },
]

let catalogSnapshot = upstreamCatalog.map((product) => ({ ...product }))
let lastSyncedAt = null

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))

  return catalogSnapshot.map((product) => ({ ...product }))
}

export async function syncCatalogFromUpstream() {
  // Simulate pulling thousands of SKUs from ERP/PIM
  await new Promise((resolve) => setTimeout(resolve, 1500))

  catalogSnapshot = upstreamCatalog.map((product) => ({
    ...product,
    price: product.price + Math.floor(Math.random() * 20),
    inventory: Math.max(
      0,
      product.inventory + Math.floor(Math.random() * 10) - 5,
    ),
    available: product.inventory > 0,
  }))
  lastSyncedAt = new Date().toISOString()
}

export function getLastSyncedAt() {
  return lastSyncedAt
}

